CREATE POLICY "user-space own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'user-space' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "user-space own insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'user-space' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "user-space own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'user-space' AND (storage.foldername(name))[1] = auth.uid()::text);